.stocksmart-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e7edf3;
    background: linear-gradient(160deg, #11161d 0%, #1a232e 55%, #161d26 100%);
    border-radius: 16px;
}

.stocksmart-container * {
    box-sizing: border-box;
}

.stocksmart-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #1c2630 0%, #233140 55%, #2a3b4d 100%);
    border: 1px solid #33485c;
    border-radius: 14px;
    margin-bottom: 18px;
    box-shadow: 0 12px 30px rgba(0, 0, 0, 0.38);
}

.stocksmart-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.stocksmart-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffc14d;
    background: rgba(255, 193, 77, 0.10);
    border: 1px solid rgba(255, 193, 77, 0.36);
    padding: 5px 14px;
    border-radius: 4px;
}

.stocksmart-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #aebfce;
}

.stocksmart-network {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.stocksmart-node {
    flex: 1;
    background: #1b242e;
    border: 1px solid #2e3f50;
    border-radius: 10px;
    padding: 14px 18px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.stocksmart-node-cdc { border-left: 5px solid #3d8bff; }
.stocksmart-node-rsp { border-left: 5px solid #ffc14d; }

.stocksmart-node-name {
    font-weight: 800;
    font-size: 1rem;
    color: #e7edf3;
}

.stocksmart-node-cdc .stocksmart-node-name { color: #6fb0ff; }
.stocksmart-node-rsp .stocksmart-node-name { color: #ffce73; }

.stocksmart-node-meta {
    font-size: 0.8rem;
    color: #8ea2b6;
    line-height: 1.4;
}

.stocksmart-node-arrow {
    align-self: center;
    font-size: 1.7rem;
    font-weight: 800;
    color: #ffc14d;
}

.stocksmart-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.95rem;
    font-weight: 600;
    color: #9fb2c5;
    margin-bottom: 16px;
    padding: 2px 4px;
}

.stocksmart-period-counter #currentDay,
.stocksmart-period-counter #maxPeriods {
    font-weight: 800;
    color: #ffc14d;
}

.stocksmart-round-name {
    background: rgba(61, 139, 255, 0.16);
    color: #6fb0ff;
    padding: 3px 12px;
    border-radius: 4px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.stocksmart-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffce73;
    background: rgba(255, 193, 77, 0.12);
    border: 1px solid rgba(255, 193, 77, 0.30);
    padding: 4px 12px;
    border-radius: 4px;
}

.stocksmart-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.stocksmart-status-card {
    background: #1b242e;
    border: 1px solid #2b3a49;
    border-radius: 10px;
    padding: 16px 16px 14px;
    border-top: 4px solid #3d8bff;
}

.stocksmart-card-fill { border-top-color: #2fbf71; }
.stocksmart-card-inv { border-top-color: #3d8bff; }
.stocksmart-card-turns { border-top-color: #ffc14d; }
.stocksmart-card-pl { border-top-color: #b388ff; }

.stocksmart-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8197ac;
}

.stocksmart-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #ffffff;
    font-variant-numeric: tabular-nums;
}

.stocksmart-card-fill .stocksmart-value { color: #2fbf71; }
.stocksmart-card-inv .stocksmart-value { color: #6fb0ff; }
.stocksmart-card-turns .stocksmart-value { color: #ffce73; }
.stocksmart-card-pl .stocksmart-value { color: #b388ff; }

.stocksmart-sublabel {
    font-size: 0.75rem;
    color: #7c91a6;
    line-height: 1.35;
}

.stocksmart-card-fill.stocksmart-fill-danger { border-top-color: #ff5d5d; }
.stocksmart-card-fill.stocksmart-fill-danger .stocksmart-value { color: #ff5d5d; }
.stocksmart-card-fill.stocksmart-fill-warn { border-top-color: #ffc14d; }
.stocksmart-card-fill.stocksmart-fill-warn .stocksmart-value { color: #ffce73; }

.stocksmart-card-inv.stocksmart-inv-danger { border-top-color: #ff5d5d; }
.stocksmart-card-inv.stocksmart-inv-danger .stocksmart-value { color: #ff8a8a; }
.stocksmart-card-inv.stocksmart-inv-good { border-top-color: #2fbf71; }
.stocksmart-card-inv.stocksmart-inv-good .stocksmart-value { color: #2fbf71; }

.stocksmart-card-pl.stocksmart-pl-pos .stocksmart-value { color: #2fbf71; }
.stocksmart-card-pl.stocksmart-pl-neg .stocksmart-value { color: #ff8a8a; }

.stocksmart-pool-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1b242e;
    border: 1px solid #3a4a3a;
    color: #9fb2c5;
    padding: 10px 18px;
    border-radius: 8px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.9rem;
}

.stocksmart-pool-bar #poolDisplay {
    font-size: 1.1rem;
    letter-spacing: 0.3px;
    color: #ff8a8a;
    font-weight: 800;
}

.stocksmart-pool-bar.stocksmart-pool-done #poolDisplay { color: #2fbf71; }
.stocksmart-pool-bar.stocksmart-pool-mid #poolDisplay { color: #ffce73; }

.stocksmart-briefing {
    display: flex;
    gap: 14px;
    background: #1b242e;
    border: 1px solid #2b3a49;
    border-left: 5px solid #ffc14d;
    border-radius: 10px;
    padding: 16px 18px;
    margin-bottom: 18px;
}

.stocksmart-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.stocksmart-briefing-title {
    font-weight: 800;
    font-size: 1.06rem;
    color: #ffce73;
    margin-bottom: 6px;
}

.stocksmart-briefing-text {
    font-size: 0.94rem;
    line-height: 1.55;
    color: #c2d2e1;
}

.stocksmart-briefing-text strong { color: #6fb0ff; }
.stocksmart-briefing-text em { color: #ffce73; font-style: italic; }

.stocksmart-controls {
    background: #1b242e;
    border: 1px solid #2b3a49;
    border-radius: 10px;
    padding: 20px 22px;
    margin-bottom: 18px;
}

.stocksmart-controls h3 {
    margin: 0 0 14px;
    font-size: 1.1rem;
    font-weight: 800;
    color: #ffffff;
    border-bottom: 2px solid #2e3f50;
    padding-bottom: 8px;
}

.stocksmart-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.9rem;
    color: #c2d2e1;
    margin: 14px 0 6px;
}

.stocksmart-container select,
.stocksmart-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #3a4c5e;
    border-radius: 7px;
    font-size: 0.9rem;
    background-color: #11181f;
    color: #e7edf3;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.stocksmart-container select:focus,
.stocksmart-container input[type="number"]:focus {
    outline: none;
    border-color: #ffc14d;
    box-shadow: 0 0 0 3px rgba(255, 193, 77, 0.18);
}

.stocksmart-container select option {
    background-color: #11181f;
    color: #e7edf3;
}

.stocksmart-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #ffc14d;
}

.stocksmart-range-readout {
    font-size: 0.86rem;
    font-weight: 700;
    color: #9fb2c5;
    margin-top: 4px;
}

.stocksmart-range-readout span:nth-child(2) {
    color: #ffce73;
    font-weight: 800;
}

.stocksmart-hint {
    font-size: 0.8rem;
    color: #8197ac;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.stocksmart-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.stocksmart-container .btn-primary {
    background: linear-gradient(135deg, #d98a16 0%, #ffc14d 100%);
    border: none;
    color: #1a1206;
    padding: 11px 26px;
    border-radius: 7px;
    box-shadow: 0 8px 18px rgba(217, 138, 22, 0.30);
}

.stocksmart-container .btn-primary:hover {
    filter: brightness(1.07);
}

.stocksmart-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #3a4c5e;
    color: #9fb2c5;
    background: transparent;
}

.stocksmart-coach {
    background: linear-gradient(160deg, #14202b 0%, #182734 100%);
    border: 1px solid #2e4256;
    color: #c8d8e7;
    border-radius: 10px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.28);
}

.stocksmart-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffc14d;
    margin-bottom: 8px;
}

.stocksmart-coach-body {
    font-size: 0.94rem;
    line-height: 1.55;
}

.stocksmart-coach-body strong { color: #6fb0ff; }
.stocksmart-coach-body em { color: #ffce73; font-style: italic; }

.stocksmart-history,
.stocksmart-chart {
    background: #1b242e;
    border: 1px solid #2b3a49;
    border-radius: 10px;
    padding: 18px 20px;
    margin-bottom: 18px;
}

.stocksmart-history h3,
.stocksmart-chart h3 {
    margin: 0 0 14px;
    font-size: 1.06rem;
    font-weight: 800;
    color: #ffffff;
}

.stocksmart-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.86rem;
    color: #c2d2e1;
}

.stocksmart-container table#usfHistoryTable th {
    background: #14202b;
    color: #ffce73;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.7rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #2e3f50;
}

.stocksmart-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #243240;
    color: #c2d2e1;
}

.stocksmart-container table#usfHistoryTable tr:nth-child(even) td {
    background: #18212b;
}

.stocksmart-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .stocksmart-container {
        padding: 14px;
    }
    .stocksmart-header h1 {
        font-size: 1.7rem;
    }
    .stocksmart-network {
        flex-direction: column;
    }
    .stocksmart-node-arrow {
        transform: rotate(90deg);
    }
    .stocksmart-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .stocksmart-value {
        font-size: 1.9rem;
    }
    .stocksmart-clock {
        margin-left: 0;
    }
    .stocksmart-period-counter {
        font-size: 0.86rem;
    }
    .stocksmart-pool-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .stocksmart-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 FIX B - completion / board-debrief scorecard (append-only, namespaced) ===== */
.ss-cm { padding: 12px 6px; text-align: center; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; }
.ss-cm-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #8197ac; margin-bottom: 6px; }
.ss-cm-verdict { font-size: 22px; font-weight: 700; color: #eaf2f8; margin-bottom: 8px; }
.ss-cm-score { font-size: 16px; color: #eaf2f8; margin-bottom: 16px; }
.ss-cm-score strong { color: #2fbf71; }
.ss-cm-sub { font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: #8197ac; margin-bottom: 8px; }
.ss-cm-targets { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-bottom: 16px; }
.ss-cm-target { display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border-radius: 20px; font-size: 13px; border: 1px solid transparent; }
.ss-cm-target.ss-cm-met { background: rgba(47,191,113,0.16); color: #7fe0a6; border-color: rgba(47,191,113,0.4); }
.ss-cm-target.ss-cm-missed { background: rgba(255,120,120,0.14); color: #ffa3a3; border-color: rgba(255,120,120,0.36); }
.ss-cm-tick { font-weight: 700; }
.ss-cm-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.ss-cm-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 9px 13px; background: rgba(120,150,180,0.12); border-radius: 8px; min-width: 96px; }
.ss-cm-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #8197ac; }
.ss-cm-metric strong { font-size: 16px; color: #eaf2f8; }
.ss-cm-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 720px; text-align: left; }
.ss-cm-insights li { padding: 9px 13px; margin-bottom: 7px; background: rgba(111,176,255,0.10); border-left: 3px solid #6fb0ff; border-radius: 4px; color: #d6e6f4; font-size: 13px; line-height: 1.45; }
@media (max-width: 640px) { .ss-cm-metric { min-width: 72px; } .ss-cm-verdict { font-size: 19px; } }

