(function() {
    'use strict';

    class StockSmartAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Stock Smart`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (Noordveld Components B.V.). ----
            this.START_FILL = 91.4;       // current measured fill rate (%)
            this.CONTRACT_FILL = 97;      // contractual fill rate (%)
            this.PENALTY_FILL = 95;       // below this, penalty exposure (%)
            this.START_INV = 31.0;        // inventory on hand (EUR M)
            this.COGS = 109.5;            // ~ revenue 148M x (1 - 26% margin); drives turns
            this.START_TURNS = 3.6;       // COGS / avg inventory
            this.TARGET_TURNS = 4.1;      // recovery goal
            this.DEAD_BUFFER = 5.8;       // dead RSP stock to redeploy (EUR M)
            this.PENALTY_QTR = 0.42;      // service penalty (EUR M / quarter)
            this.LOST_SALES_QTR = 0.285;  // lost-sales bleed ~95k/month x 3 (EUR M / quarter)

            // Concept truths (the modelled best answers).
            this.TRUE_SEGMENT = `cv`;
            this.TRUE_SPLIT = `pooled`;
            this.TRUE_FUNDING = `redeploy`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    fill: this.START_FILL,        // fill rate (%)
                    inventory: this.START_INV,    // inventory on hand (EUR M)
                    turns: this.START_TURNS,      // inventory turns (x)
                    pool: this.DEAD_BUFFER,       // dead RSP buffer still un-redeployed (EUR M)
                    quarterPL: 0,                 // penalty + lost-sales avoided this quarter (EUR M)
                    diagnosed: false,             // read the network correctly in R1
                    boughtOut: false,             // tried to buy the problem away
                    siloed: false,                // optimized echelons independently
                    averageRop: false,            // built ROPs on mean demand only
                    pooledRisk: false,            // exploited risk pooling
                    stressFailed: false,          // failed the R4 stress test
                    threePLSigned: false,         // board outsourced to the 3PL
                    fillHistory: [this.START_FILL],
                    invHistory: [this.START_INV],
                    turnsHistory: [this.START_TURNS],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    segment: `volume`,
                    dead: `cdc`,
                    offender: `slow`,
                    focus: 30,
                    policy: `uniform98`,
                    rop: `avg`,
                    marginal: `linear`,
                    csl: 90,
                    split: `forward`,
                    funding: `buy`,
                    coord: `silos`,
                    pool: 20,
                    supplier: `ignore`,
                    spike: `local`,
                    board: `service`,
                    rule: `moremax`
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const sg = document.getElementById(`segmentInput`);
                const dd = document.getElementById(`deadInput`);
                const of = document.getElementById(`offenderInput`);
                const fo = document.getElementById(`focusInput`);
                if (sg) decisions.segment = sg.value;
                if (dd) decisions.dead = dd.value;
                if (of) decisions.offender = of.value;
                if (fo) decisions.focus = parseInt(fo.value, 10);
                if (!Number.isFinite(decisions.focus) || decisions.focus < 0 || decisions.focus > 100) {
                    warn(`warn_focus_range`); return false;
                }
            } else if (round === 2) {
                const po = document.getElementById(`policyInput`);
                const rp = document.getElementById(`ropInput`);
                const ma = document.getElementById(`marginalInput`);
                const cs = document.getElementById(`cslInput`);
                if (po) decisions.policy = po.value;
                if (rp) decisions.rop = rp.value;
                if (ma) decisions.marginal = ma.value;
                if (cs) decisions.csl = parseInt(cs.value, 10);
                if (!Number.isFinite(decisions.csl) || decisions.csl < 80 || decisions.csl > 99) {
                    warn(`warn_csl_range`); return false;
                }
            } else if (round === 3) {
                const sp = document.getElementById(`splitInput`);
                const fu = document.getElementById(`fundingInput`);
                const co = document.getElementById(`coordInput`);
                const pl = document.getElementById(`poolInput`);
                if (sp) decisions.split = sp.value;
                if (fu) decisions.funding = fu.value;
                if (co) decisions.coord = co.value;
                if (pl) decisions.pool = parseInt(pl.value, 10);
                if (!Number.isFinite(decisions.pool) || decisions.pool < 0 || decisions.pool > 100) {
                    warn(`warn_pool_range`); return false;
                }
            } else if (round === 4) {
                const su = document.getElementById(`supplierInput`);
                const sk = document.getElementById(`spikeInput`);
                const bo = document.getElementById(`boardInput`);
                const ru = document.getElementById(`ruleInput`);
                if (su) decisions.supplier = su.value;
                if (sk) decisions.spike = sk.value;
                if (bo) decisions.board = bo.value;
                if (ru) decisions.rule = ru.value;
                if (!decisions.supplier || !decisions.spike || !decisions.board || !decisions.rule) {
                    warn(`warn_pick_all`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let fillDelta = 0, invDelta = 0;   // invDelta: change in inventory (EUR M)
            let redeploy = 0;                  // dead buffer redeployed this round (EUR M)
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: read demand and the network. Right diagnosis enables
                // everything downstream; wrong diagnosis quietly caps later gains.
                switch (d.segment) {
                    case `cv`: ds.diagnosed = true; fillDelta += 0.6; coachKey = `coach_r1_cv`; break;
                    case `volume`: fillDelta += 0.1; coachKey = `coach_r1_volume`; break;
                    case `margin`: fillDelta += 0.1; coachKey = `coach_r1_margin`; break;
                }
                switch (d.dead) {
                    case `rsp`: fillDelta += 0.4; if (d.segment === `cv`) coachKey = `coach_r1_sharp`; break;
                    case `cdc`: fillDelta -= 0.2; if (coachKey === `coach_default`) coachKey = `coach_r1_deadcdc`; break;
                    case `none`: ds.boughtOut = true; fillDelta -= 0.3; coachKey = `coach_r1_deadnone`; break;
                }
                switch (d.offender) {
                    case `fast`: fillDelta += 0.5; break;
                    case `slow`: fillDelta -= 0.1; if (coachKey === `coach_default`) coachKey = `coach_r1_offslow`; break;
                    case `all`: fillDelta -= 0.2; ds.boughtOut = true; if (coachKey === `coach_default`) coachKey = `coach_r1_offall`; break;
                }
                // Effort spent reading the data before acting (procedural quality).
                if (d.focus >= 55) { fillDelta += 0.3; }
                else if (d.focus <= 15) { fillDelta -= 0.3; }

                const sharp = (d.segment === `cv` && d.dead === `rsp` && d.offender === `fast`);
                summaryKey = sharp ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Plan: service targets and the safety-stock formula.
                // Differentiated CSL + DDLT ROP is the disciplined path.
                switch (d.policy) {
                    case `differentiated`:
                        fillDelta += 3.4; invDelta -= 0.4; coachKey = `coach_r2_diff`; break;
                    case `uniform98`:
                        // Service looks great but holding cost explodes on slow lumpy SKUs.
                        fillDelta += 4.2; invDelta += 4.2; coachKey = `coach_r2_uniform98`; break;
                    case `uniform90`:
                        // Cheap buffers everywhere — the 97% promise is never met.
                        fillDelta += 0.6; invDelta -= 0.6; coachKey = `coach_r2_uniform90`; break;
                }
                switch (d.rop) {
                    case `ddlt`: fillDelta += 2.0; break;
                    case `demandonly`: fillDelta += 0.6; ds.averageRop = true; if (coachKey === `coach_r2_diff`) coachKey = `coach_r2_demandonly`; break;
                    case `avg`: fillDelta -= 0.4; ds.averageRop = true; coachKey = `coach_r2_avgrop`; break;
                }
                if (d.marginal === `nonlinear`) { fillDelta += 0.4; }
                else { invDelta += 0.6; } // mispricing the marginal cost over-buffers slow lines

                // Fast-segment CSL: under-buffer the contract metric and the promise breaks;
                // over-buffer past ~98% and turns start to suffer for little fill-rate gain.
                if (d.csl >= 97 && d.csl <= 98) { fillDelta += 1.4; }
                else if (d.csl >= 95) { fillDelta += 0.8; }
                else if (d.csl < 93) { fillDelta -= 1.6; if (coachKey === `coach_r2_diff`) coachKey = `coach_r2_lowcsl`; }
                if (d.csl >= 99) { invDelta += 0.8; fillDelta += 0.2; } // diminishing returns, more buffer

                summaryKey = (d.policy === `differentiated` && d.rop === `ddlt`) ? `sum_r2_good` :
                             (d.policy === `uniform98` ? `sum_r2_uniform` :
                             (d.rop === `avg` ? `sum_r2_avgrop` : `sum_r2_weak`));
            } else if (round === 3) {
                // Decide: place the stock across two echelons. THE core round.
                const poolShare = d.pool / 100;

                // (a) Echelon placement.
                switch (d.split) {
                    case `pooled`:
                        ds.pooledRisk = true;
                        fillDelta += 2.8; invDelta -= 1.2; coachKey = `coach_r3_pooled`; break;
                    case `forward`:
                        // Four independent buffers for the same variability — pays for it 4x.
                        fillDelta += 1.4; invDelta += 3.0; coachKey = `coach_r3_forward`; break;
                    case `central`:
                        // Minimum stock, but the transfer day costs the 24-hour promise.
                        fillDelta -= 2.2; invDelta -= 1.6; coachKey = `coach_r3_central`; break;
                }

                // (b) Funding — the cash-neutral constraint (Common Error 4).
                switch (d.funding) {
                    case `redeploy`:
                        redeploy = Math.min(ds.pool, 4.0);
                        invDelta -= redeploy;            // misplaced cash is liquidated/repositioned
                        fillDelta += 1.0; break;
                    case `buy`:
                        ds.boughtOut = true;
                        invDelta += 4.5; fillDelta += 1.6; coachKey = `coach_r3_buy`; break;
                    case `cut`:
                        invDelta -= 3.5; fillDelta -= 2.8; coachKey = `coach_r3_cut`; break;
                }

                // (c) Network vs silo optimization (Common Error 5 / de Kok).
                switch (d.coord) {
                    case `network`: fillDelta += 1.4; invDelta -= 0.6; break;
                    case `silos`: ds.siloed = true; fillDelta -= 1.6; if (coachKey === `coach_r3_pooled`) coachKey = `coach_r3_silos`; break;
                }

                // Pooling the lumpy SKUs centrally — the square-root law.
                if (d.split === `pooled`) {
                    if (poolShare >= 0.55) { invDelta -= 1.6 * poolShare; fillDelta += 0.6; redeploy += 0.8; }
                    else if (poolShare <= 0.15) { fillDelta -= 0.6; coachKey = `coach_r3_underpool`; }
                } else if (poolShare >= 0.55 && d.split === `central`) {
                    // Pooling everything centralizes too much, hurts the 24h promise more.
                    fillDelta -= 0.6;
                }
                if (redeploy > 0) ds.pool = Math.max(0, Math.round((ds.pool - redeploy) * 10) / 10);

                summaryKey = (d.split === `pooled` && d.funding === `redeploy` && d.coord === `network`) ? `sum_r3_good` :
                             (d.funding === `buy` ? `sum_r3_buy` :
                             (d.split === `forward` ? `sum_r3_forward` :
                             (d.coord === `silos` ? `sum_r3_silos` : `sum_r3_weak`)));
            } else if (round === 4) {
                // Recover: stress-test and defend.
                // Shock 1 — supplier lead time 3 -> 6 weeks. Average-demand ROPs fail here.
                switch (d.supplier) {
                    case `recompute`:
                        fillDelta += 1.6; invDelta += 0.4;
                        if (ds.averageRop) { fillDelta += 0.4; } // recovering, but you start exposed
                        break;
                    case `ignore`:
                        ds.stressFailed = true;
                        fillDelta -= (ds.averageRop ? 4.0 : 2.4); coachKey = `coach_r4_ignore`; break;
                    case `panic`:
                        invDelta += 4.0; fillDelta += 0.8; coachKey = `coach_r4_panic`; break;
                }

                // Shock 2 — Düsseldorf +40%. The central pool is built to absorb this.
                switch (d.spike) {
                    case `ship`:
                        if (ds.pooledRisk) { fillDelta += 2.0; coachKey = `coach_r4_ship`; }
                        else { fillDelta += 0.4; coachKey = `coach_r4_shipnopool`; } // no pool to lateral-ship from
                        break;
                    case `local`:
                        invDelta += 2.6; fillDelta += 0.8; if (coachKey === `coach_default`) coachKey = `coach_r4_local`; break;
                    case `relax`:
                        ds.stressFailed = true; fillDelta -= 2.2; if (coachKey === `coach_default`) coachKey = `coach_r4_relax`; break;
                }

                // Board defence — naming the frontier (service AND cash) is the point.
                switch (d.board) {
                    case `frontier`: fillDelta += 0.6; if (coachKey === `coach_default`) coachKey = `coach_r4_frontier`; break;
                    case `service`: if (coachKey === `coach_default`) coachKey = `coach_r4_service`; break;
                    case `cash`: if (coachKey === `coach_default`) coachKey = `coach_r4_cash`; break;
                }

                // The institutionalized rule.
                if (d.rule === `jointecholon`) { fillDelta += 0.4; }
                else if (d.rule === `moremax`) { invDelta += 0.8; }

                summaryKey = (d.supplier === `recompute` && d.spike === `ship` && d.board === `frontier`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Diagnosis cap: a wrong R1 read limits how high fill can climb. ----
            // ---- Apply fill-rate and inventory deltas (clamped). ----
            ds.fill = Math.max(60, Math.min(99.5, Math.round((ds.fill + fillDelta) * 10) / 10));
            if (!ds.diagnosed) ds.fill = Math.min(ds.fill, 95.4); // never truly nailed the target blind

            ds.inventory = Math.max(20, Math.round((ds.inventory + invDelta) * 10) / 10);

            // ---- Turns are DERIVED from inventory: turns = COGS / inventory. ----
            ds.turns = Math.round((this.COGS / ds.inventory) * 10) / 10;

            // ---- Quarterly service P&L: penalty + lost-sales AVOIDED this quarter. ----
            // Full credit at/above the contract; penalty exposure returns below 95%.
            let penaltyAvoided = 0, lostAvoided = 0;
            if (ds.fill >= this.PENALTY_FILL) penaltyAvoided = this.PENALTY_QTR;
            else penaltyAvoided = -this.PENALTY_QTR; // exposed
            // Lost-sales bleed scales with the gap to the contract fill rate.
            const gap = Math.max(0, this.CONTRACT_FILL - ds.fill);
            lostAvoided = this.LOST_SALES_QTR * (1 - Math.min(1, gap / (this.CONTRACT_FILL - this.START_FILL)));
            // Buying out of the problem burns cash even if fill rises — net working-capital penalty.
            let cashPenalty = 0;
            if (ds.inventory > this.START_INV) cashPenalty = (ds.inventory - this.START_INV) * 0.12; // carrying drag
            ds.quarterPL = Math.round((penaltyAvoided + lostAvoided - cashPenalty) * 100) / 100;

            ds.fillHistory.push(ds.fill);
            ds.invHistory.push(ds.inventory);
            ds.turnsHistory.push(ds.turns);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 FIX A - persist the composite where the gradebook / reporting layer reads it
            const _c = this._composite(ds);
            ds.score = _c;
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = _c;
            return {
                period: state.currentPeriod,
                score: _c,
                overallScore: _c,
                fill: ds.fill,
                fillDelta: Math.round(fillDelta * 10) / 10,
                inventory: ds.inventory,
                invDelta: Math.round(invDelta * 10) / 10,
                turns: ds.turns,
                pool: ds.pool,
                quarterPL: ds.quarterPL,
                redeploy: Math.round(redeploy * 10) / 10,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`fillDisplay`, `domainState.fill`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.stocksmart-card-fill`);
                if (card) {
                    card.classList.toggle(`stocksmart-fill-danger`, n < self.PENALTY_FILL);
                    card.classList.toggle(`stocksmart-fill-warn`, n >= self.PENALTY_FILL && n < self.CONTRACT_FILL);
                }
                return `${self._fmt1(n)}%`;
            });

            uiManager.bind(`invDisplay`, `domainState.inventory`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.stocksmart-card-inv`);
                if (card) {
                    card.classList.toggle(`stocksmart-inv-danger`, n > self.START_INV + 0.05);
                    card.classList.toggle(`stocksmart-inv-good`, n <= self.START_INV - 1.0);
                }
                return `€${self._fmt1(n)}M`;
            });

            uiManager.bind(`turnsDisplay`, `domainState.turns`, (v) => `${self._fmt1(Number(v))}×`);

            uiManager.bind(`plDisplay`, `domainState.quarterPL`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.stocksmart-card-pl`);
                if (card) {
                    card.classList.toggle(`stocksmart-pl-pos`, n >= 0);
                    card.classList.toggle(`stocksmart-pl-neg`, n < 0);
                }
                const sign = n < 0 ? `−` : `+`;
                return `${sign}€${self._fmt1(Math.abs(n))}M`;
            });

            uiManager.bind(`poolDisplay`, `domainState.pool`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.stocksmart-pool-bar`);
                if (bar) {
                    bar.classList.toggle(`stocksmart-pool-done`, n <= 0.5);
                    bar.classList.toggle(`stocksmart-pool-mid`, n > 0.5 && n < self.DEAD_BUFFER - 0.5);
                }
                return `€${self._fmt1(n)}M`;
            });

            // Focus slider readout.
            const fo = document.getElementById(`focusInput`);
            const foReadout = document.getElementById(`focusReadout`);
            if (fo && foReadout) {
                foReadout.textContent = fo.value;
                fo.addEventListener(`input`, function() { foReadout.textContent = fo.value; });
            }

            // Pool slider readout.
            const pl = document.getElementById(`poolInput`);
            const plReadout = document.getElementById(`poolShareReadout`);
            if (pl && plReadout) {
                plReadout.textContent = pl.value;
                pl.addEventListener(`input`, function() { plReadout.textContent = pl.value; });
            }
        }

        _fmt1(v) {
            // Locale-aware one-decimal: en "31.0", es "31,0".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(1);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

