        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.fillHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                stockChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.fillHistory.map((v) => Math.round(v * 10) / 10) },
                        { data: ds.invHistory.map((v) => Math.round(v * 10) / 10) },
                        { data: ds.turnsHistory.map((v) => Math.round(v * 10) / 10) }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0 - verbatim v1.0.0 composite formula (weights 0.45/0.32/0.23 sum to 1).
            const fill = Math.round(ds.fill * 10) / 10;
            const inventory = Math.round(ds.inventory * 10) / 10;
            const turns = Math.round(ds.turns * 10) / 10;
            const fillScore = Math.max(0, Math.min(100, (fill - 85) / (this.CONTRACT_FILL - 85) * 100));
            const cashScore = Math.max(0, Math.min(100, (this.START_INV + 1 - inventory) / (this.START_INV + 1 - 24) * 100));
            const turnsScore = Math.max(0, Math.min(100, (turns - 3.4) / (this.TARGET_TURNS - 3.4) * 100));
            return Math.round(fillScore * 0.45 + cashScore * 0.32 + turnsScore * 0.23);
        }

        formatCompletionMessage(summary) {
            // v1.1.0 FIX B - localized board-debrief scorecard (was: framework default that discarded
            // score, tier, targets and insights).
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            const score = (summary.composite != null) ? summary.composite : (summary.score != null ? summary.score : 0);
            const verdict = summary.gradeKey ? t(summary.gradeKey) : (summary.performance || '');
            const insights = summary.insights || [];
            const chip = function (ok, label) {
                return '<div class="ss-cm-target ' + (ok ? 'ss-cm-met' : 'ss-cm-missed') + '">'
                    + '<span class="ss-cm-tick">' + (ok ? '✓' : '✗') + '</span><span>' + label + '</span></div>';
            };
            const targets = ''
                + chip(!!summary.serviceMet, t('tgt_service'))
                + chip(!!summary.penaltySafe, t('tgt_penalty'))
                + chip(!!summary.cashNeutral, t('tgt_cash'))
                + chip(!!summary.turnsRecovered, t('tgt_turns'));
            const metric = function (label, val) {
                return '<div class="ss-cm-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            const f1 = (typeof this._fmt1 === 'function') ? this._fmt1.bind(this) : function (v) { return v; };
            const fillStr = (summary.fill != null) ? (f1(summary.fill) + '%') : '-';
            const invStr = (summary.inventory != null) ? ('€' + f1(summary.inventory) + 'M') : '-';
            const turnsStr = (summary.turns != null) ? (f1(summary.turns) + '×') : '-';
            const metrics = ''
                + metric(t('kpi_fill'), fillStr)
                + metric(t('kpi_inventory'), invStr)
                + metric(t('kpi_turns'), turnsStr);
            const items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            return ''
                + '<div class="ss-cm">'
                +   '<div class="ss-cm-heading">' + t('comp_heading') + '</div>'
                +   '<div class="ss-cm-verdict">' + verdict + '</div>'
                +   '<div class="ss-cm-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="ss-cm-sub">' + t('comp_targets_heading') + '</div>'
                +   '<div class="ss-cm-targets">' + targets + '</div>'
                +   '<div class="ss-cm-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="ss-cm-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };
            const ds = window.mySimulation.state.domainState;
            const fill = Math.round(ds.fill * 10) / 10;
            const inventory = Math.round(ds.inventory * 10) / 10;
            const turns = Math.round(ds.turns * 10) / 10;

            const serviceMet = fill >= this.CONTRACT_FILL;
            const penaltySafe = fill >= this.PENALTY_FILL;
            const cashNeutral = inventory <= this.START_INV + 0.05;
            const turnsRecovered = turns >= this.TARGET_TURNS - 0.05;

            // Composite: service is the contract metric, then cash discipline, then turns.
            // v1.1.0 FIX A - delegated to _composite(ds) so the persisted per-round score and this
            // completion composite are identical by construction (verbatim v1.0.0 formula).
            const composite = this._composite(ds);

            // v1.1.0 FIX C - tier resolved to an i18n key and localized via t() (was hardcoded English).
            let perfKey = `grade_outsourced`;
            if (serviceMet && cashNeutral && turnsRecovered && composite >= 80) perfKey = `grade_frontier`;
            else if (penaltySafe && cashNeutral) perfKey = `grade_promise`;
            else if (serviceMet && !cashNeutral) perfKey = `grade_bought`;
            else if (!penaltySafe) perfKey = `grade_penalty`;
            else perfKey = `grade_mixed`;
            const performance = t(perfKey);

            ds.threePLSigned = (perfKey === `grade_outsourced` || perfKey === `grade_penalty`);

            const insights = [];
            if (serviceMet && cashNeutral && turnsRecovered) insights.push(window.mySimulation.t(`insight_frontier`));
            else if (serviceMet && !cashNeutral) insights.push(window.mySimulation.t(`insight_bought`));
            else if (!penaltySafe) insights.push(window.mySimulation.t(`insight_penalty`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.boughtOut && !cashNeutral) insights.push(window.mySimulation.t(`insight_cashneutral`));
            if (ds.pooledRisk && cashNeutral) insights.push(window.mySimulation.t(`insight_pooling`));
            if (ds.siloed) insights.push(window.mySimulation.t(`insight_silo`));
            if (ds.averageRop && ds.stressFailed) insights.push(window.mySimulation.t(`insight_rop`));
            if (!ds.diagnosed) insights.push(window.mySimulation.t(`insight_diagnosis`));
            if (turnsRecovered && cashNeutral) insights.push(window.mySimulation.t(`insight_turns`));

            return {
                gradeKey: perfKey,
                score: composite,
                fill: fill,
                inventory: inventory,
                turns: turns,
                serviceMet: serviceMet,
                penaltySafe: penaltySafe,
                cashNeutral: cashNeutral,
                turnsRecovered: turnsRecovered,
                threePLSigned: ds.threePLSigned,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.fill < this.PENALTY_FILL) return window.mySimulation.t(`hint_penalty`);
            if (ds.inventory > this.START_INV + 0.05) return window.mySimulation.t(`hint_cash`);
            if (ds.siloed && state.currentPeriod >= 3) return window.mySimulation.t(`hint_silo`);
            if (ds.averageRop && state.currentPeriod >= 2) return window.mySimulation.t(`hint_rop`);
            if (!ds.pooledRisk && state.currentPeriod >= 3) return window.mySimulation.t(`hint_pool`);
            if (ds.fill >= this.CONTRACT_FILL && ds.inventory <= this.START_INV) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.fill`, label: `Fill`, i18nKey: `col_fill`, formatter: (v) => `${self._fmt1(Number(v))}%` },
                { key: `results.inventory`, label: `Inventory`, i18nKey: `col_inv`, formatter: (v) => `€${self._fmt1(Number(v))}M` },
                { key: `results.turns`, label: `Turns`, i18nKey: `col_turns`, formatter: (v) => `${self._fmt1(Number(v))}×` },
                { key: `results.quarterPL`, label: `Service P&L`, i18nKey: `col_pl`, formatter: (v) => `${Number(v) < 0 ? `−` : `+`}€${self._fmt1(Math.abs(Number(v)))}M` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

        getTranslations() {
            return {
                en: {
